cd /Users/jyl/work/repo/ai-agent-live/super-planer/pocs/frontend && head -30 scripts/shot.mjs | grep -n import; cat > .shots/v05-scrollprobe.mjs <<'EOF'
import { chromium } from "playwright";
const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 1586, height: 992 } });
await p.goto("http://localhost:3200/document"); await p.waitForLoadState("networkidle");
const r = await p.evaluate(() => [...document.querySelectorAll("*")].filter(e => { const s = getComputedStyle(e); return /auto|scroll/.test(s.overflowY) && e.scrollHeight > e.clientHeight; }).map(e => ({ tag: e.tagName, cls: e.className.toString().slice(0, 120), sh: e.scrollHeight, ch: e.clientHeight, ow: e.offsetWidth - e.clientWidth })));
console.log(JSON.stringify(r, null, 1)); await b.close();
EOF
cp .shots/v05-scrollprobe.mjs scripts/../.shots/ 2>/dev/null; node .shots/v05-scrollprobe.mjs

